# XUnity 會把 _AutoGeneratedTranslations.txt 當成自己的輸出檔重寫（切換語言時的 Prune），
# 重寫時只保留「原文=譯文」，regex 規則與註解全部消失。
# 所以把中文化的翻譯搬到 WSZH_Translations.txt（XUnity 一樣會讀，但不會改寫），
# _AutoGeneratedTranslations.txt 只留一行註解（語言切換需要這個檔案存在）。
# tw / cn 在 v1.7.1 已經被清掉，從 v1.7.0 的版本還原；hk 沒有被清過，用目前的內容。
import os, re, subprocess
REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SIM = r'C:\Users\Gary\Desktop\WS模擬器'
GOOD = 'a5520fb'          # v1.7.0
AUTO = '_AutoGeneratedTranslations.txt'
STUB = '// 中文化套件的翻譯在 WSZH_Translations.txt（這個檔案由翻譯外掛自動寫入，請勿放翻譯）\n'

def fix(s):
    # 判定圖示的提示：圖示名稱不限
    s = re.sub(r'<sprite\[\^>\]\*mini_[a-z]+\[\^>\]\*>', '<sprite[^>]*>', s)
    return s

for lang in ('tw', 'hk', 'cn'):
    rel = 'files/AutoTranslator/Translation/%s/Text/%s' % (lang, AUTO)
    if lang == 'hk':
        content = open(os.path.join(REPO, rel), encoding='utf-8-sig').read()
    else:
        content = subprocess.run(['git', 'show', '%s:%s' % (GOOD, rel)], cwd=REPO, capture_output=True).stdout.decode('utf-8-sig')
    content = fix(content.replace('\r\n', '\n'))
    if 'WSZH_Translations' in content or content.count('\n') < 900:
        raise SystemExit('%s: 內容看起來不對（%d 行），停止' % (lang, content.count('\n')))
    for root in (os.path.join(REPO, 'files', 'AutoTranslator'), os.path.join(SIM, 'AutoTranslator')):
        d = os.path.join(root, 'Translation', lang, 'Text')
        open(os.path.join(d, 'WSZH_Translations.txt'), 'w', encoding='utf-8-sig', newline='\n').write(content)
        open(os.path.join(d, AUTO), 'w', encoding='utf-8-sig', newline='\n').write(STUB)
    print(lang, content.count('\n'), 'lines, rules', len(re.findall(r'^s?r:"', content, re.M)))
